import React from 'react';
import { BrowserRouter, Routes, Route } from 'react-router-dom';
import Navbar from './layouts/Navbar';
import Footer from './layouts/Footer';
import HeroSection from './features/hero/HeroSection';
import VisionMissionValues from './features/visionmissionvalues/VisionMissionValues';
import ImpactStats from './features/impact-stats/ImpactStats';
import NewsSection from './features/news/NewsSection';
import PartnersSection from './features/partners/PartnersSection';
import DonationSection from './features/donation/DonationSection';
import WhatWeDoSection from './pages/about-us/WhatWeDo';
import CleoneOnTheFrontline from './pages/about-us/CleoneOnTheFrontline';
import OurPeople from './pages/about-us/OurPeople';
import ResearchPage from './pages/Research';
import ContactPage from './pages/Contact';
import DonatePage from './pages/get-involved/Donate';
import NewsPage from './pages/News';
import FullNewsArticle from './pages/FullNewsArticle';
import VolunteerPage from './pages/get-involved/Volunteer';
import OurFriendsPage from './pages/get-involved/OurFriends';
import LoginPage from './pages/admin/login/Login';
import AdminNewsPage from './pages/admin/news/News';
import AddNewsPage from './pages/admin/news/AddNews';
import EditNewsPage from './pages/admin/news/EditNews';
import './App.css';
import ScrollToTop from './components/ScrollToTop';
import StripeDonationSection from './features/donation/StripeDonationSection';
import ProtectedRoute from './ProtectedRoute';
import NotAuthorised from './pages/admin/NotAuthorised';

const App: React.FC = () => {
  const HomePageContent = (
    <>
      <HeroSection />
      <VisionMissionValues />
      <ImpactStats />
      <NewsSection />
      <PartnersSection />
      <StripeDonationSection />
      <div className="whiteDivider"></div>
    </>
  );

  return (
    <BrowserRouter>
      <ScrollToTop />
      <Navbar />
      <Routes>
        <Route path="/" element={HomePageContent} />
        <Route path="/for-a-cure-foundation" element={HomePageContent} />
        <Route path="/about">
          <Route path="what-we-do" element={<WhatWeDoSection />} />
          <Route path="cleone-on-the-frontline" element={<CleoneOnTheFrontline />} />
          <Route path="our-people" element={<OurPeople />} />
        </Route>
        <Route path="/research" element={<ResearchPage />} />
        <Route path="/contact" element={<ContactPage />} />
        <Route path="/get-involved">
          <Route path="donate" element={<DonatePage />} />
          <Route path="volunteer" element={<VolunteerPage />} />
          <Route path="our-friends" element={<OurFriendsPage />} />
        </Route>
        <Route path="/news" element={<NewsPage />} />
        <Route path="/news/:slug" element={<FullNewsArticle />} />
        <Route path="/not-authorised" element={<NotAuthorised />} />

        <Route path="/admin/login" element={<LoginPage />} />
      
        <Route path="/admin/news" element={<ProtectedRoute><AdminNewsPage /></ProtectedRoute>} />
        <Route path="/admin/news/add-news" element={<ProtectedRoute><AddNewsPage /></ProtectedRoute>} />
        <Route path="/admin/news/edit/:id" element={<ProtectedRoute><EditNewsPage /></ProtectedRoute      >} />
      
      </Routes>
      <Footer />
    </BrowserRouter>
  );
};

export default App; 